import raw from './bookMeta.json';
import type { BookMeta } from './types';

/** Generated by `npm run asset:export`. Do not edit bookMeta.json by hand. */
export const bookMeta = raw as unknown as BookMeta;

/** Viewports at or below this width use the mobile camera and poster. */
export const NARROW_QUERY = '(max-width: 639.98px)';

export const MODEL_PATH = 'models/book.glb';

export function assetUrl(path: string): string {
  return import.meta.env.BASE_URL + path;
}
